function contactUndoParent(MemoryConnection $db,string $suffix,string $sourceId='token-player',string $unitId='character-player'):array {
 $before=[];foreach($db->domains as$key=>$record)$before[$key]=$record['payload'];
 $def=['version'=>1,'geometry'=>'path','radiusCells'=>.08,'damage'=>['formula'=>'1d20','damageType'=>'magical'],'affectCaster'=>false,'affectAllies'=>false,'affectEnemies'=>true,'trigger'=>'contact-during-target-turn','maximumPerTargetTurn'=>1,'expiry'=>'source-next-turn-start','style'=>'silver-filament'];
 $zone=applicationCreateContactZone($def,['id'=>'contact-zone-'.$suffix,'sceneId'=>'scene-one','layerId'=>'ground','sourceTokenId'=>$sourceId,'sourceUnitId'=>$unitId,'sourceControllerId'=>$sourceId==='token-player'?'account-player':'account-gm','originExecutionId'=>'contact-origin-'.$suffix,'initiative'=>$db->payload('initiative:scene-one'),'now'=>100,'origin'=>['x'=>20,'y'=>50]]);
 $zone=applicationAppendContactZonePath($zone,[['x'=>20,'y'=>50],['x'=>60,'y'=>50]]);$store=$db->payload('devices')?:dsEmpty();$store['contactZones'][]=$zone;$db->put('devices',$store);
 $activity=$db->payload('activity');$actionId='action-contact-parent-'.$suffix;$activity['playerActions'][]=['id'=>$actionId,'kind'=>'ability','summary'=>'Contact parent '.$suffix];$db->put('activity',$activity);
 $after=[];foreach($db->domains as$key=>$record)$after[$key]=$record['payload'];combatUndoRecord($before,$after,'ability.complex',['action'=>'start','sceneId'=>'scene-one','sourceTokenId'=>$sourceId,'requestId'=>'parent-request-'.$suffix],['execution'=>['id'=>'contact-origin-'.$suffix,'abilityName'=>'Contact '.$suffix]]);$db->put('activity',$after['activity']);return ['zone'=>$zone,'actionId'=>$actionId];
}
function contactUndoAction(MemoryConnection $db,string $id):TestResponse{return runCommand($db,'action.undo',['actionId'=>$id,'requestId'=>'contact-undo-'.randomToken(20)],true);}
// Two overlapping zones remain two independent causal histories.
$db=contactUndoFixture();$a=contactUndoParent($db,'overlap-alpha');$b=contactUndoParent($db,'overlap-beta');$clock=$db->payload('initiative:scene-one');$db->put('initiative:scene-one',[...$clock,'turnSerial'=>11,'currentIndex'=>1]);
