$receipts=array_values(array_filter($db->payload('activity')['attackReceipts']??[],static fn($r)=>isset($r['attack']['contactZoneId'])));specialCheck(count($receipts)===2,'Each origin has one environmental receipt');$damageB=0;foreach($receipts as$r)if($r['attack']['originExecutionId']==='contact-origin-overlap-beta')$damageB=$r['attack']['appliedDamage'];
$actions=$db->payload('activity')['combatActions'];specialCheck(count($actions)===2&&count(array_filter($actions,static fn($a)=>in_array('execution:contact-origin-overlap-alpha',$a['aliases'],true)&&in_array('execution:contact-origin-overlap-beta',$a['aliases'],true)))===0,'The two source spells are never merged by a shared contact callback');
$pos=$db->payload('token:scene-one:token-monster');specialCheck(contactUndoAction($db,$a['actionId'])->status===200,'First source can be undone independently');specialCheck($db->payload('token:scene-one:token-monster')['hp']===100-$damageB,'Undo first origin preserves the second origin damage');specialCheck(array_column($db->payload('devices')['contactZones'],'id')===[$b['zone']['id']],'Undo first origin preserves second filament');specialCheck(contactUndoAction($db,$b['actionId'])->status===200,'Second source can then be undone');specialCheck($db->payload('token:scene-one:token-monster')['hp']===100&&$db->payload('token:scene-one:token-monster')['y']===$pos['y'],'Both causal undos restore HP while preserving foreign movement');

