$db=contactUndoFixture();$parent=contactUndoParent($db,'enemy-charge');$enemy=$db->payload('token:scene-one:token-monster');$ability=json_decode(file_get_contents(__DIR__.'/fixtures/charge-ability.json'),true,512,JSON_THROW_ON_ERROR);$ability['id']='ability-566f321d-ca05-4b02-92ad-8149076076e6';$ability['name']='BÃ©lier';$enemy=[...$enemy,'abilities'=>[$ability],'mana'=>50,'maxMana'=>50,'fatigue'=>['current'=>0,'max'=>150],'stats'=>[['id'=>'character-stat-force','label'=>'Force','value'=>'100']],'weaponAttacks'=>[['id'=>'enemy-charge-main','formula'=>'1d2','damageType'=>'physical','reach'=>'reach']]];$db->put('token:scene-one:token-monster',$enemy);$clock=$db->payload('initiative:scene-one');$db->put('initiative:scene-one',[...$clock,'turnSerial'=>11,'currentIndex'=>1]);
$r=runCommand($db,'ability.complex',['action'=>'start','sceneId'=>'scene-one','sourceTokenId'=>'token-monster','abilityId'=>$ability['id'],'requestId'=>'enemy-charge-start-'.randomToken(16),'initialSelection'=>['allocations'=>[['tokenId'=>'token-player','count'=>1]]],'chargeSelection'=>['allocations'=>[['tokenId'=>'token-player','count'=>1]]]],true);$r=fixtureApproveDefenseGate($db,$r);specialCheck($r->status===200,'Enemy charge has its own approved execution: '.json_encode($r->body));$e=$r->body['execution'];
$r=runCommand($db,'ability.complex',['action'=>'command','executionId'=>$e['id'],'expectedRevision'=>$e['revision'],'requestId'=>'enemy-charge-hop-'.randomToken(16),'command'=>['action'=>'prepare-target','targetTokenId'=>'token-player']],true);specialCheck($r->status===200,'Enemy charge really moves across the filament: '.json_encode($r->body));
$cues=$db->payload('activity')['abilityCueEvents']??[];specialCheck(count(array_filter($cues,static fn($event)=>($event['completionCue']['spell']['presetId']??'')==='token-body-charge'))===1,'The shared PHP charge publishes a normalized body-charge cue');
$moved=$db->payload('token:scene-one:token-monster');specialCheck($moved['hp']<100&&($moved['fatigue']['current']??0)===10,'Contact and charge cost both apply once');
$activity=$db->payload('activity');$parentAction=null;$chargeAction=null;foreach($activity['combatActions']as$action){if(in_array('execution:contact-origin-enemy-charge',$action['aliases'],true))$parentAction=$action;if(in_array('execution:'.$e['id'],$action['aliases'],true))$chargeAction=$action;}
specialCheck($parentAction!==null&&$chargeAction!==null&&$parentAction['id']!==$chargeAction['id'],'Environmental cause cannot merge with the victim charge');
$contactIds=[];foreach($activity['attackReceipts']as$receipt)if(($receipt['attack']['originExecutionId']??'')==='contact-origin-enemy-charge')$contactIds[]=$receipt['attack']['id'];$journal=array_values(array_filter($activity['playerActions'],static fn($entry)=>in_array($entry['operation']['requestId']??'',array_map(static fn($id)=>'damage-'.$id,$contactIds),true)));
specialCheck($journal!==[]&&array_filter($journal,static fn($entry)=>($entry['combatActionId']??'')!==$parentAction['id'])===[],'Contact journal stays attached to Hira, never reannotated by the enclosing charge');
specialCheck(contactUndoAction($db,$parent['actionId'])->status===200,'Hira can undo her damage during an enemy charge');$restored=$db->payload('token:scene-one:token-monster');specialCheck($restored['hp']===100&&$restored['x']===$moved['x']&&$restored['y']===$moved['y']&&$restored['fatigue']===$moved['fatigue'],'Undo Hira preserves victim charge position and fatigue');
specialCheck(contactUndoAction($db,$chargeAction['actionIds'][0])->status===200,'Enemy charge can be undone separately');$restored=$db->payload('token:scene-one:token-monster');specialCheck($restored['hp']===100&&($restored['fatigue']['current']??0)===0&&$restored['x']===$enemy['x']&&$restored['y']===$enemy['y'],'Second undo never credits the contact HP twice');

